class Solution {
    public boolean isReachable(int targetX, int targetY) {
        long g = gcd(targetX, targetY);
        return (g & (g - 1)) == 0;
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

