class Solution:
    def isReachable(self, targetX: int, targetY: int) -> bool:
        x, y = targetX, targetY
        while x % 2 == 0 and y % 2 == 0:
            x //= 2; y //= 2
        while (x, y) != (1, 1):
            if x < y: x, y = y, x
            if y == 0: return False
            x -= y
            if x == 0: return False
        return True

