class Solution {
public:
    bool isReachable(long long targetX, long long targetY) {
        long long x = targetX, y = targetY;
        while (x % 2 == 0 && y % 2 == 0) { x /= 2; y /= 2; }
        while (!(x == 1 && y == 1)) {
            if (x < y) swap(x, y);
            if (y == 0 || x == y) return false;
            x -= y;
        }
        return true;
    }
};

