class Solution {
    public boolean isReachable(int tx, int ty) {
        long x = tx, y = ty;
        while (x % 2 == 0 && y % 2 == 0) { x /= 2; y /= 2; }
        while (!(x == 1 && y == 1)) {
            if (x < y) { long t = x; x = y; y = t; }
            if (y == 0 || x == y) return false;
            x -= y;
        }
        return true;
    }
}

